describe('Modal with Tabbed Content', () => {
    beforeEach(() => {
        cy.visit('/your-page-url'); // Replace with the actual URL
        cy.get('.open-modal-button').click(); // Adjust selector to open the modal
    });

    it('should remember the active tab after closing and reopening the modal', () => {
        cy.get('.tab-button').contains('Tab 1').click();
        cy.get('.tab-content').should('contain', 'Content for Tab 1');

        cy.get('.close-modal-button').click(); // Adjust selector to close the modal
        cy.get('.open-modal-button').click(); // Reopen the modal

        cy.get('.tab-button.active').should('contain', 'Tab 1');
        cy.get('.tab-content').should('contain', 'Content for Tab 1');
    });

    it('should switch to the correct tab when clicked', () => {
        cy.get('.tab-button').contains('Tab 2').click();
        cy.get('.tab-content').should('contain', 'Content for Tab 2');

        cy.get('.tab-button').contains('Tab 1').click();
        cy.get('.tab-content').should('contain', 'Content for Tab 1');
    });
});
